head.script:
// jQuery 조회 순서(받은 선택자 → 없으면 mf_ 접두사). 2026-11
scwin.__getJq = function(q) {
    var j = $(q); if (j.length) return j;
    var P = 'mf_', t = q.trim(), r = t.slice(1);
    if (r.slice(0, 2) === 'G_') r = 'G_' + P + r.slice(2); else if (r.slice(0, P.length) !== P) r = P + r;
    return $(t.slice(0, 1) + r);
};
scwin.trigger1_onclick = function(e) {
    windowContainer1.createWindow("test_popup", null, "windowContainer_SKT-571_(WSQ-1152)_sub1.xml");
    windowContainer1.createWindow("test_popup2", null, "windowContainer_SKT-571_(WSQ-1152)_sub2.xml");
};
scwin.__windowCreated = function() {
    return scwin.getNumEleChildren("#windowContainer1_window") == 2 && (scwin.getNumEleChildren("#windowContainer1_name") == 2);
}
scwin.getNumEleChildren = function(id) {
    return scwin.__getJq(id).children().length;
}
scwin.__isShowPopup = function() {
    var container = ((j) => j.length ? j : $('#mf_windowContainer1_subWindow0'))($('#windowContainer1_subWindow0'));
    var iframe = scwin.__getJq(container).find('#'+$p.id+'windowContainer1_subWindow0_iframe').contents();
    var pop = iframe.find("#popup1");
    return pop.length > 0 && scwin.__getJq(container).css("display") == "block";
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
}
